import { expect, test } from 'vitest';

const prefix =
  'A synthetic workspace entry has a long diagnostic before its observed disposition. ' +
  'The repeated context ensures a reporter that limits its assertion headline cannot show the final clause. ';
const expected = prefix + 'The example loader refuses this target.';
const different = prefix + 'The example loader ignores this target.';
const appended = expected + ' Additional context follows.';

function load(message) {
  throw new Error(message);
}

function messageFrom(operation) {
  try {
    operation();
  } catch (error) {
    if (error instanceof Error) return error.message;
    throw error;
  }
  throw new Error('Expected the synthetic operation to throw');
}

test('substring exact-message control', () => {
  expect(() => load(expected)).toThrow(expected);
});

test('equality exact-message control', () => {
  expect(messageFrom(() => load(expected))).toBe(expected);
});

test('substring different final clause', () => {
  expect(() => load(different)).toThrow(expected);
});

test('equality different final clause', () => {
  expect(messageFrom(() => load(different))).toBe(expected);
});

test('substring extra context control', () => {
  expect(() => load(appended)).toThrow(expected);
});

test('equality extra context control', () => {
  expect(messageFrom(() => load(appended))).toBe(expected);
});
